const resources = Object.fromEntries(appLanguages.map(({ code }) => [
  code,
  { translation: code === 'en' ? en : { ...sharedTranslations[code], ...(code === 'te' ? te : {}), ...interfaceTranslations[code], ...extendedInterfaceTranslations[code], ...supplementalInterfaceTranslations[code] } },
]));
const initialLanguage = getInterfaceLanguage(
  typeof localStorage === 'undefined' ? undefined : localStorage.getItem('bharatsathi-language'),
) ?? 'en';

i18n.use(initReactI18next).init({
  lng: initialLanguage,
  fallbackLng: 'en',
  supportedLngs: interfaceLanguages.map(({ code }) => code),
  resources,
  interpolation: { escapeValue: false },
});

if (typeof document !== 'undefined') {
  const syncDocumentLanguage = (language: string) => {
    const interfaceLanguage = getInterfaceLanguage(language) ?? 'en';
    document.documentElement.lang = interfaceLanguage;
    document.title = i18n.t('BharatSathi AI — Your Government Benefits Companion', { lng: interfaceLanguage });
  };
  syncDocumentLanguage(i18n.resolvedLanguage ?? initialLanguage);
  i18n.on('languageChanged', syncDocumentLanguage);
}

export default i18n;
